import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.BW2T23B9.js";const b=JSON.parse('{"title":"设置系统","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1787830168000}'),i={name:"guide/settings.md"};function l(n,t,o,h,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="设置系统" tabindex="-1">设置系统 <a class="header-anchor" href="#设置系统" aria-label="Permalink to &quot;设置系统&quot;">​</a></h1><p>设置分为学习、音频、可访问性、AI、数据、Anki 引擎以及系统与实验。设置项必须连接到运行时行为；尚未接入的实验项应禁用并标注状态。</p><h2 id="设置分区" tabindex="-1">设置分区 <a class="header-anchor" href="#设置分区" aria-label="Permalink to &quot;设置分区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>典型内容</th></tr></thead><tbody><tr><td>Learning</td><td>目标保持率、学习与复习偏好</td></tr><tr><td>Audio &amp; Haptics</td><td>自动朗读、母语、音效、触觉</td></tr><tr><td>Accessibility</td><td>文本缩放、减少动态、高对比等</td></tr><tr><td>AI Tools</td><td>Provider、模型、凭据、预算与数据清理</td></tr><tr><td>Data</td><td>缓存、导出、存储维护</td></tr><tr><td>Anki Engine</td><td>渲染、网络、解密、媒体和牌组覆盖</td></tr><tr><td>System &amp; Experiments</td><td>系统健康、安全模式、调度实验和已接入实验项</td></tr></tbody></table><h2 id="anki-引擎设置" tabindex="-1">Anki 引擎设置 <a class="header-anchor" href="#anki-引擎设置" aria-label="Permalink to &quot;Anki 引擎设置&quot;">​</a></h2><p>全局默认可以被单牌组覆盖。覆盖项包括：</p><ul><li>渲染模式。</li><li>JavaScript。</li><li>智能预渲染。</li><li>抓取延时。</li><li>网络策略。</li></ul><p>删除覆盖后立即继承全局值。恢复默认值只重置高级偏好与牌组覆盖，不修改复习历史、导入数据、AI 配置、主题或无障碍偏好。</p><h2 id="存储维护" tabindex="-1">存储维护 <a class="header-anchor" href="#存储维护" aria-label="Permalink to &quot;存储维护&quot;">​</a></h2><p>存储页区分不可再生成数据和可再生成数据：</p><table tabindex="0"><thead><tr><th>数据</th><th>清理行为</th></tr></thead><tbody><tr><td>课程数据库</td><td>不在普通缓存清理中删除</td></tr><tr><td>Anki Collection / 学习状态</td><td>不在普通缓存清理中删除</td></tr><tr><td>Anki 媒体</td><td>仅通过明确的牌组或媒体维护操作处理</td></tr><tr><td>预渲染缓存</td><td>可清理，下次按需生成</td></tr><tr><td>AI 缓存</td><td>可清理，不删除课程和会话真相源</td></tr><tr><td>日志</td><td>可独立清理，不自动改变系统健康分数</td></tr></tbody></table><p>数据库完整性检查使用只读 <code>PRAGMA integrity_check</code>。索引维护使用 <code>REINDEX</code> 和 <code>PRAGMA optimize</code>。这些操作不得附带删除学习数据。</p><h2 id="系统健康" tabindex="-1">系统健康 <a class="header-anchor" href="#系统健康" aria-label="Permalink to &quot;系统健康&quot;">​</a></h2><p>本地监控按最近 24 小时事件评分：warning 计 1，error 计 3，fatal 至少提升到 40。同一指纹 60 秒内只累计一次分，但保留真实次数。</p><table tabindex="0"><thead><tr><th style="text-align:right;">分数</th><th>状态</th></tr></thead><tbody><tr><td style="text-align:right;">0–9</td><td>正常</td></tr><tr><td style="text-align:right;">10–39</td><td>需要注意</td></tr><tr><td style="text-align:right;">≥40 或 fatal</td><td>严重</td></tr></tbody></table><p>严重状态会进入系统健康页面。确认处理使分数降低 40，最低为 0。新事件仍可再次触发。</p><h2 id="安全模式" tabindex="-1">安全模式 <a class="header-anchor" href="#安全模式" aria-label="Permalink to &quot;安全模式&quot;">​</a></h2><p>安全模式临时关闭实验功能、模板脚本和外部卡片网络。它不覆盖已保存偏好。退出后恢复原配置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li><li><a href="/docs/guide/accessibility">可访问性</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',20)])])}const u=a(i,[["render",l]]);export{b as __pageData,u as default};
